    val codes = listOf(
        ToolReferenceEntry("g2_enable", "SETUP", "Enable Marvin mode", "Open the character/status screen, type marvin, then close it. Use your configured status key (usually B or C).", command = "marvin", source = "https://www.worldofgothic.com/gothic2/?go=g2cheats", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g2_console", "SHORTCUTS", "Open the console", "With Marvin active, press F2, enter a command and press Enter. Press F2 again to close the console.", command = "F2", source = "https://www.worldofgothic.com/gothic2/?go=g2cheats", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g2_disable", "SETUP", "Disable Marvin mode", "Open the status screen, type 42 and close it. This stops debug mode but does not undo changes already made.", command = "42", source = "https://www.worldofgothic.com/gothic2/?go=g2cheats", codeCategory = CodeCategory.GENERAL),
