    val tips = listOf(
        ToolReferenceEntry("g2_tip_save", "STARTING OUT", "Keep several save slots", "Keep an earlier save before guild decisions, difficult fights and sailing away. Saving in one slot removes your fallback.", source = "https://www.worldofgothic.com/gothic2/?go=g2faq"),
        ToolReferenceEntry("g2_tip_build", "TRAINING", "Choose a main combat style", "Focus your early learning points on one weapon style and its supporting attribute. Spreading them across every skill delays a reliable fighting build.", source = "https://www.worldofgothic.com/gothic2/?go=g2faq"),
        ToolReferenceEntry("g2_tip_danger", "EXPLORATION", "Return to strong enemies later", "The countryside includes enemies much stronger than an early hero. Retreat and return with improved equipment and training.", source = "https://www.worldofgothic.com/gothic2/?go=g2faq"),
        ToolReferenceEntry("g2_tip_journal", "QUESTS", "Re-read the journal", "Read new journal entries after important conversations. They often clarify who to visit next or what item to bring.", source = "https://www.worldofgothic.com/gothic2/?go=g2faq"),
        ToolReferenceEntry("g2_tip_scrolls", "MAGIC", "Non-mages can use scrolls", "Scrolls provide access to spells without following the fire-mage path. They are consumable and still need mana.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/magicke-svitky/"),
        ToolReferenceEntry("g2_tip_runes", "MAGIC", "Runes and scrolls work differently", "Runes are reusable; ordinary mage runes require the relevant magic circle. A spawned rune does not bypass that requirement.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/magicke-runy/"),
        ToolReferenceEntry("g2_tip_tablets", "NIGHT OF THE RAVEN", "Learn the ancient languages", "Myxir teaches the language levels needed for magical tablets. A higher-level tablet requires the corresponding language knowledge.", source = "https://www.gothicz.net/gothic-2-noc-havrana/kamenne-tabulky/"),
        ToolReferenceEntry("g2_tip_bonuses", "NIGHT OF THE RAVEN", "Plan permanent bonuses", "In unmodified NotR, permanent attribute bonuses can push training into higher cost brackets. Consider training first, then consuming saved bonuses. Mods may handle this differently.", source = "https://www.gothicz.net/gothic-2-noc-havrana/kamenne-tabulky/"),
        ToolReferenceEntry("g2_tip_materials", "CRAFTING", "Keep rare recipe ingredients", "Do not sell rare plants or dragon materials blindly. Check future potion, rune and equipment recipes before clearing your inventory.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/herbar/"),
        ToolReferenceEntry("g2_tip_harvest", "HUNTING", "Learn harvesting before the hunt", "Acquire the specific trophy skill before hunting for skins, plates, blood or scales. Different trophies require different knowledge.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/trofeje/"),
        ToolReferenceEntry("g2_tip_ammo", "RANGED COMBAT", "Pack the correct ammunition", "Bows use arrows and crossbows use bolts. Expansion magic weapons have their own special ammunition.", source = "https://www.gothicz.net/marvin/g2/insert-kody/predmety/kuse/"),
